<script setup>
import { onMounted,ref } from 'vue'; import { supabase } from '../lib/supabase'; import { getSuppliers } from '../services/data'
const suppliers=ref([]),editing=ref(null),loading=ref(true),saving=ref(false),error=ref('');const empty=()=>({name:'',default_lead_time_days:2,contact:'',notes:''});async function load(){try{suppliers.value=await getSuppliers()}catch{error.value='Dobaviteljev ni bilo mogoče naložiti.'}finally{loading.value=false}}onMounted(load);async function save(){saving.value=true;try{const {error:e}=editing.value.id?await supabase.from('suppliers').update(editing.value).eq('id',editing.value.id):await supabase.from('suppliers').insert(editing.value);if(e)throw e;editing.value=null;await load()}catch{error.value='Dobavitelja ni bilo mogoče shraniti.'}finally{saving.value=false}}
</script><template><section class="page"><header class="row-head"><div><p class="eyebrow">ADMINISTRACIJA</p><h1>Dobavitelji</h1></div><button @click="editing=empty()">Dodaj</button></header><form v-if="editing" class="card stack" @submit.prevent="save"><label>Ime<input v-model="editing.name" required /></label><label>Privzet dobavni rok v dnevih<input v-model="editing.default_lead_time_days" type="number" min="0" required /></label><label>Kontakt<input v-model="editing.contact" /></label><label>Opombe<textarea v-model="editing.notes" /></label><div class="actions"><button type="button" class="secondary" @click="editing=null">Prekliči</button><button :disabled="saving">Shrani</button></div></form><p v-if="error" class="error">{{error}}</p><div v-if="loading" class="center-state">Nalagam dobavitelje …</div><button v-for="s in suppliers" v-else class="list-row button-row" @click="editing={...s}"><span><strong>{{s.name}}</strong><small>Dobavni rok: {{s.default_lead_time_days}} dni</small></span></button></section></template>
